alter table public.governance add column if not exists email text, add column if not exists phone text, add column if not exists address text;
drop function if exists public.create_governance_entity(text, public.governance_type, text, text, timestamptz, timestamptz, uuid, text, text);
drop function if exists public.create_governance_entity(text, public.governance_type, text, text, timestamptz, timestamptz, uuid, text, text, text);
create function public.create_governance_entity(p_name text,p_type public.governance_type,p_short_name text default null,p_status text default 'active',p_valid_from timestamptz default now(),p_valid_to timestamptz default null,p_category_id uuid default null,p_image_url text default null,p_website text default null,p_email text default null,p_phone text default null,p_address text default null,p_description text default null) returns public.governance language plpgsql security definer set search_path=public,pg_catalog as $$ declare v_row public.governance; begin perform public.require_governance_admin(); if nullif(btrim(p_name),'') is null then raise exception 'Name is required.'; end if; if p_status not in ('active','inactive','deprecated') then raise exception 'Invalid governance status.'; end if; if p_valid_from is null then raise exception 'Valid from is required.'; end if; if p_valid_to is not null and p_valid_to<p_valid_from then raise exception 'Valid to cannot be earlier than valid from.'; end if; if p_status in ('inactive','deprecated') and p_valid_to is null then raise exception 'Valid to is required for inactive or deprecated entities.'; end if; insert into public.governance(type,name,short_name,description,website,email,phone,address,status,valid_from,valid_to,category_id,image_url,created_by,updated_by) values(p_type,btrim(p_name),nullif(btrim(p_short_name),''),nullif(btrim(p_description),''),nullif(btrim(p_website),''),nullif(btrim(p_email),''),nullif(btrim(p_phone),''),nullif(btrim(p_address),''),p_status,p_valid_from,p_valid_to,p_category_id,nullif(btrim(p_image_url),''),auth.uid(),auth.uid()) returning * into v_row; return v_row; end; $$;
drop function if exists public.update_governance_entity(uuid,text,text,text,text,public.governance_type,text,timestamptz,timestamptz,text,uuid);
create function public.update_governance_entity(p_entity_id uuid,p_name text,p_short_name text default null,p_description text default null,p_website text default null,p_type public.governance_type default null,p_status text default 'active',p_valid_from timestamptz default null,p_valid_to timestamptz default null,p_image_url text default null,p_category_id uuid default null,p_email text default null,p_phone text default null,p_address text default null) returns public.governance language plpgsql security definer set search_path=public as $$ declare v_row public.governance; begin perform public.require_governance_admin(); if p_entity_id is null or not exists(select 1 from public.governance where id=p_entity_id) then raise exception 'Governance entity not found'; end if; if nullif(btrim(p_name),'') is null then raise exception 'Name is required'; end if; if p_status not in ('active','inactive','deprecated') then raise exception 'Invalid governance status'; end if; if p_valid_from is null then raise exception 'Valid from is required'; end if; if p_valid_to is not null and p_valid_to<p_valid_from then raise exception 'Valid to cannot be earlier than valid from'; end if; if p_status in ('inactive','deprecated') and p_valid_to is null then raise exception 'Valid to is required for inactive or deprecated entities'; end if; update public.governance set name=btrim(p_name),short_name=nullif(btrim(p_short_name),''),description=nullif(btrim(p_description),''),website=nullif(btrim(p_website),''),email=nullif(btrim(p_email),''),phone=nullif(btrim(p_phone),''),address=nullif(btrim(p_address),''),type=coalesce(p_type,type),status=p_status,valid_from=p_valid_from,valid_to=p_valid_to,image_url=nullif(btrim(p_image_url),''),category_id=p_category_id,updated_by=auth.uid(),updated_at=now() where id=p_entity_id returning * into v_row; return v_row; end; $$;